//! § 2 large data outside the backup, § 3 Docker data a rebuild could lose, § 5 application state.

use std::collections::BTreeSet;
use std::path::Path;

use serde_json::Value;

use super::{Live, Section, human};
use crate::backup::{Coverage, HOST_SYSTEM_PATHS, Identity, under};
use crate::host::FileKind;
use crate::snapshot::View;

/// Regenerated by reinstalling packages or pulling images: big, and never a loss.
const REGENERABLE: [&str; 18] = [
    "/var/lib/docker/overlay2",
    "/var/lib/docker/image",
    "/var/lib/docker/buildkit",
    "/var/lib/docker/containers",
    "/var/lib/docker/tmp",
    "/var/lib/containerd",
    "/var/lib/apt",
    "/var/lib/snapd",
    "/var/cache",
    "/var/lib/dpkg",
    "/var/lib/docker/network",
    "/var/lib/docker/swarm",
    "/var/lib/docker/plugins",
    "/var/lib/systemd",
    "/var/lib/ubuntu-advantage",
    "/var/lib/command-not-found",
    "/var/lib/man-db",
    "/var/lib/fwupd",
];

const LARGE: u64 = 200 * 1024 * 1024;

fn text(v: &Value) -> &str {
    v.as_str().unwrap_or_default()
}

/// `…/backups/2026-11-26_0330`: a dated backup run.
fn backup_run_dir(path: &str) -> bool {
    path.split('/').collect::<Vec<_>>().windows(2).any(|w| {
        let b = w[1].as_bytes();
        (w[0] == "backup" || w[0] == "backups")
            && b.len() >= 10
            && b[..4].iter().all(u8::is_ascii_digit)
            && b[4] == b'-'
            && b[7] == b'-'
    })
}

pub(super) fn large(view: &View<'_>, identity: &Identity, live: &Live) -> Section {
    let mut s = Section::new("large", "Large data not covered by the backup");
    if let Some(note) = &live.sizing_note {
        s.info(note.clone());
        return s;
    }
    if !identity.enabled {
        s.info("backups are not configured (`[backup]`), so nothing here is covered");
    }
    let paths: BTreeSet<&String> = live.sizes.keys().collect();
    let mut rows: Vec<(u64, Vec<String>)> = Vec::new();
    let mut fungible_seen = BTreeSet::new();
    for (path, size) in &live.sizes {
        // report the leaves: a directory whose children were measured is described by them
        if *size < LARGE || paths.iter().any(|other| other.starts_with(&format!("{}/", path.trim_end_matches('/')))) {
            continue;
        }
        let note = match identity.coverage(path) {
            Coverage::Covered(_) | Coverage::Dumped(_) => continue,
            Coverage::Fungible(reason) => {
                let root = identity.fungible_root(path).map(|(root, _)| root.clone()).unwrap_or_default();
                if !fungible_seen.insert(root) {
                    continue;
                }
                if reason.is_empty() { "fungible".to_string() } else { format!("fungible ({reason})") }
            }
            Coverage::UndumpedDatabase(db) => format!("✗ database files of {db}, and nothing dumps it"),
            Coverage::NotCovered if backup_run_dir(path) => "local backup copies".to_string(),
            Coverage::NotCovered if REGENERABLE.iter().any(|r| under(path, r)) => {
                "regenerable (images/packages/cache)".to_string()
            }
            Coverage::NotCovered
                if path.split('/').any(|part| part == ".cache" || part == "cache" || part == "Cache") =>
            {
                "regenerable (cache)".to_string()
            }
            Coverage::NotCovered if path.ends_with("/docker/volumes") => {
                // du reports the volumes directory as one number; judge it by the volumes in it
                let uncovered: Vec<String> = view
                    .volumes()
                    .iter()
                    .filter_map(|v| v["name"].as_str())
                    .filter(|name| {
                        matches!(
                            identity.coverage(&format!("{path}/{name}/_data")),
                            Coverage::NotCovered | Coverage::UndumpedDatabase(_)
                        )
                    })
                    .map(str::to_string)
                    .collect();
                if uncovered.is_empty() {
                    continue;
                }
                format!("✗ docker volumes not in the backup: {}", uncovered.join(", "))
            }
            Coverage::NotCovered => "✗ not backed up".to_string(),
        };
        // a fungible root is shown once, with the size of the root itself when known
        let (shown_path, shown_size) = match identity.fungible_root(path) {
            Some((root, _)) => (root.clone(), live.sizes.get(root).copied().unwrap_or(*size)),
            None => (path.clone(), *size),
        };
        rows.push((shown_size, vec![human(shown_size), shown_path, note]));
    }
    rows.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1[1].cmp(&b.1[1])));
    let gaps = rows.iter().filter(|(_, r)| r[2].starts_with('✗')).count();
    if gaps > 0 {
        s.gap(format!(
            "{gaps} large director{} outside the backup (see the table)",
            if gaps == 1 { "y is" } else { "ies are" }
        ));
    }
    s.table(&["Size", "Path", "Note"], rows.into_iter().take(60).map(|(_, r)| r).collect());
    s.or_nothing("nothing over 200 MB outside the backup")
}

/// (host path, what it is, read-only) of everything that holds application data.
fn data_locations(view: &View<'_>) -> Vec<(String, String, bool)> {
    let mut out = BTreeSet::new();
    let system = |src: &str| HOST_SYSTEM_PATHS.iter().any(|p| under(src, p));
    for c in view.containers() {
        for m in c["mounts"].as_array().into_iter().flatten() {
            let (source, ro) = (text(&m["source"]), m["ro"] == true);
            match text(&m["type"]) {
                "bind" if !source.is_empty() && !system(source) => {
                    out.insert((
                        source.to_string(),
                        format!("bind mount → {}:{}", text(&c["name"]), text(&m["destination"])),
                        ro,
                    ));
                }
                "volume" if !text(&m["name"]).is_empty() => {
                    out.insert((
                        format!("/var/lib/docker/volumes/{}/_data", text(&m["name"])),
                        format!("volume {} → {}", text(&m["name"]), text(&c["name"])),
                        ro,
                    ));
                }
                _ => {}
            }
        }
    }
    for service in view.services() {
        for m in service["mounts"].as_array().into_iter().flatten() {
            let (source, ro) = (text(&m["source"]), m["ro"] == true);
            let name = text(&service["name"]);
            match text(&m["type"]) {
                "bind" if !source.is_empty() && !system(source) => {
                    out.insert((
                        source.to_string(),
                        format!("bind mount → swarm service {name}:{}", text(&m["destination"])),
                        ro,
                    ));
                }
                "volume" if !source.is_empty() => {
                    out.insert((
                        format!("/var/lib/docker/volumes/{source}/_data"),
                        format!("volume {source} → swarm service {name}"),
                        ro,
                    ));
                }
                _ => {}
            }
        }
    }
    for project in view.compose_projects() {
        if !text(&project["workdir"]).is_empty() {
            out.insert((
                text(&project["workdir"]).to_string(),
                format!("compose stack dir ({})", text(&project["project"])),
                false,
            ));
        }
    }
    for instance in view.incus_instances() {
        out.insert(("/var/lib/incus".to_string(), format!("Incus instance {instance} (disk + config)"), false));
    }
    out.into_iter().collect()
}

pub(super) fn docker(view: &View<'_>, identity: &Identity, live: &Live) -> Section {
    let mut s = Section::new("docker", "Docker data a rebuild could lose");
    let mut fungible_seen = BTreeSet::new();
    for (path, what, read_only) in data_locations(view) {
        match identity.coverage(&path) {
            Coverage::Covered(_) => {}
            Coverage::Fungible(reason) => {
                if let Some((root, _)) = identity.fungible_root(&path)
                    && fungible_seen.insert(root.clone())
                {
                    let why = if reason.is_empty() { String::new() } else { format!(": {reason}") };
                    s.finding(super::Level::Fungible, format!("`{root}`{why}"));
                }
            }
            Coverage::Dumped(db) => {
                s.review(format!("`{path}` — {what}: raw database files, covered by the dump of {db}"))
            }
            Coverage::UndumpedDatabase(db) => {
                s.gap(format!("`{path}` — {what}: database files of {db}, and `backup.databases` does not dump it"))
            }
            // a read-only mount of something owned elsewhere is a view, not this container's data
            Coverage::NotCovered if read_only => {}
            Coverage::NotCovered => s.gap(format!("`{path}` — {what}: not in the backup")),
        }
    }
    for (name, bytes) in &live.size_rw {
        if *bytes > 100 * 1024 * 1024 {
            s.gap(format!("container **{name}** has {} written inside the container itself (not in a volume): lost when it is recreated", human(*bytes)));
        }
    }
    let services: Vec<String> = view.services().iter().map(|x| text(&x["name"]).to_string()).collect();
    for image in &live.local_images {
        let repo = image.split(':').next().unwrap_or(image);
        if services.iter().any(|name| name == repo) {
            s.review(format!(
                "image **{image}** has no registry digest: built by Dokploy from git, which rebuilds it on redeploy"
            ));
        } else if !image.starts_with("<none>") {
            s.review(format!("image **{image}** has no registry digest (built locally?): it cannot be pulled again — keep its build context captured or push it to a registry"));
        }
    }
    if !services.is_empty() {
        s.review(format!("{} swarm services: a rebuild needs their definitions back before they can be redeployed (for Dokploy: Dokploy itself and its Postgres data)", services.len()));
    }
    s.or_nothing("nothing found")
}

pub(super) fn app_state(view: &View<'_>, identity: &Identity, live: &Live) -> Section {
    let mut s = Section::new("state", "Application state outside the usual places");
    let host = view.host();
    let state_dir = view.state().root().display().to_string();
    let mut rows = Vec::new();
    for base in ["/var/lib", "/opt", "/srv"] {
        for name in host.read_dir(Path::new(base)).unwrap_or_default() {
            let path = format!("{base}/{name}");
            let is_dir = host.symlink_metadata(Path::new(&path)).is_ok_and(|m| m.kind == FileKind::Dir);
            let size = live.sizes.get(&path).copied();
            let captured = view.captured(&path);
            if !is_dir
                || live.package_owned.contains(&path)
                || REGENERABLE.iter().any(|r| under(&path, r))
                || path == state_dir
                || path == "/var/lib/docker"
                || (size.is_some_and(|sz| sz < 64 * 1024) && !captured)
            {
                continue;
            }
            let coverage = match identity.coverage(&path) {
                Coverage::Covered(_) | Coverage::Dumped(_) => "✓".to_string(),
                Coverage::Fungible(_) => "fungible".to_string(),
                // a directory that only *contains* covered things (stack dirs in /opt/services) is fine
                _ if identity.paths.iter().any(|(covered, _)| under(covered, &path)) => "✓ (its contents)".to_string(),
                _ => "✗".to_string(),
            };
            rows.push(vec![
                path,
                size.map(human).unwrap_or_default(),
                if captured { "yes" } else { "" }.to_string(),
                coverage,
            ]);
        }
    }
    let gaps: Vec<&str> = rows.iter().filter(|r| r[3] == "✗").map(|r| r[0].as_str()).collect();
    if !gaps.is_empty() {
        s.gap(format!("not in the backup: {}", gaps.iter().map(|p| format!("`{p}`")).collect::<Vec<_>>().join(", ")));
    }
    s.table(&["Path", "Size", "Config captured", "In backup"], rows);
    s.or_nothing("nothing")
}
